/* @autogenerated */
import { mockRepository } from 'app/shared/testing/feature-testing';
import { repositories } from './repositories.config';

describe('repositories', () => {
  it('has the repository of the 33 entities', () => {
    expect(Object.keys(repositories).length).toBe(33);
  });

  it('loads each repository under the name of its metadata', async () => {
    const api = mockRepository('api') as any;
    for (const [name, load] of Object.entries(repositories)) {
      const type: any = await load();
      expect(type.metadata(api).name).toBe(name);
    }
  });
});
